-- Phase 9: apply only via the approved migration runner after a verified backup.
CREATE TABLE admin_audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_user_id INT UNSIGNED NOT NULL,action VARCHAR(100) NOT NULL,target_type VARCHAR(80) NOT NULL,target_id INT UNSIGNED NULL,reason TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY admin_audit_actor_created_idx(actor_user_id,created_at),KEY admin_audit_target_idx(target_type,target_id),CONSTRAINT admin_audit_actor_fk FOREIGN KEY(actor_user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE equipment_reports (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,item_id INT UNSIGNED NOT NULL,reporter_user_id INT UNSIGNED NOT NULL,reason VARCHAR(255) NOT NULL,details TEXT NULL,status ENUM('open','reviewing','resolved','dismissed') NOT NULL DEFAULT 'open',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY equipment_reports_item_status_idx(item_id,status),CONSTRAINT equipment_reports_item_fk FOREIGN KEY(item_id) REFERENCES items(id),CONSTRAINT equipment_reports_user_fk FOREIGN KEY(reporter_user_id) REFERENCES users(id)) ENGINE=InnoDB;
ALTER TABLE users ADD COLUMN verification_decided_by INT UNSIGNED NULL,ADD COLUMN verification_decided_at DATETIME NULL,ADD COLUMN verification_reason VARCHAR(1000) NULL,ADD CONSTRAINT users_verification_admin_fk FOREIGN KEY(verification_decided_by) REFERENCES users(id);
ALTER TABLE items ADD COLUMN moderation_status ENUM('visible','hidden','suspended') NOT NULL DEFAULT 'visible',ADD COLUMN moderation_reason VARCHAR(1000) NULL,ADD COLUMN moderated_by INT UNSIGNED NULL,ADD COLUMN moderated_at DATETIME NULL;
